'use strict';
const $=s=>document.querySelector(s),canvas=$('#game'),ctx=canvas.getContext('2d');
const chars=[['마리오','🍄','#f35c58'],['루이지','🟢','#6ed584'],['피치','👑','#f59bc5'],['요시','🦖','#91d85f'],['키노피오','🍄','#79caff'],['쿠파','🐢','#edb851']];
let selected=0,racers=[],state='menu',elapsed=0,keys={},last=0,count=0,boost=0,shield=0,held=null,flash=0,muted=false,audio,beat=0,toastTimer=0,particles=[];
const LENGTH=6000,MAX=270;let me;
chars.forEach((ch,i)=>{let b=document.createElement('button');b.className='char'+(!i?' active':'');b.innerHTML=`<b>${ch[1]}</b><span>${ch[0]}</span>`;b.onclick=()=>{selected=i;document.querySelectorAll('.char').forEach((e,j)=>e.classList.toggle('active',i===j));tone(500+i*60,.08)};$('#characters').append(b)});
function init(){racers=chars.map((c,i)=>({id:i,d:0,x:(i-2.5)*.25,v:0,skill:205+Math.random()*20,phase:Math.random()*6,finish:0}));me=racers[selected];me.x=0;elapsed=0;boost=0;shield=0;held=null;count=3.2;state='count';$('#overlay').style.display='none';$('#item').firstChild.textContent='🎁';startAudio();tone(523,.15);updateGrid()}
$('#start').onclick=init;
function startAudio(){if(!audio)audio=new(window.AudioContext||window.webkitAudioContext)();audio.resume()}
function tone(freq,d=.12,type='square',vol=.035){if(!audio||muted)return;let o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(vol,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+d)}
const melody=[659,659,659,0,659,659,659,0,659,784,523,587,659,0,0,0,698,698,698,698,698,659,659,659,659,587,587,659,587,784,0,0];
setInterval(()=>{if(state!=='race'&&state!=='count')return;let n=melody[beat%melody.length];if(n)tone(n,.14,'square',.018);if(beat%2===0)tone([131,165,175,196][Math.floor(beat/8)%4],.19,'triangle',.035);beat++},185);
$('#sound').onclick=()=>{startAudio();muted=!muted;$('#sound').textContent=muted?'♫ SOUND OFF':'♫ SOUND ON'};
function toast(t){$('#toast').textContent=t;toastTimer=2}
function item(){if(state!=='race'||!held)return;let h=held;held=null;if(h==='🚀'){boost=3;toast('로켓 부스터! 🚀')}if(h==='⭐'){shield=5;boost=2;toast('무적의 별! ⭐')}if(h==='❄️'){racers.filter(r=>r!==me&&r.d>me.d).forEach(r=>r.d-=135);toast('앞선 카트에 눈보라! ❄️')}tone(900,.3,'sawtooth',.025);$('#item').firstChild.textContent='🎁'}$('#item').onclick=item;
function pause(){if(state==='race'){state='paused';$('#countdown').textContent='PAUSED'}else if(state==='paused'){state='race';$('#countdown').textContent=''}}
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.code==='Space'&&!e.repeat)item();if(e.code==='KeyP'&&!e.repeat)pause()});window.addEventListener('keyup',e=>keys[e.code]=false);window.addEventListener('blur',()=>{keys={};if(state==='race')pause()});
document.querySelectorAll('[data-key]').forEach(b=>{b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[b.dataset.key]=true};b.onpointerup=b.onpointercancel=()=>keys[b.dataset.key]=false});
function updateGrid(){let order=[...racers].sort((a,b)=>b.d-a.d);$('#standings').innerHTML=order.map((r,i)=>`<div class="racer"><b>${chars[r.id][1]}</b>${chars[r.id][0]}<small>${i+1}위 ${r===me?'· YOU':'· CPU'}</small></div>`).join('');$('#position').innerHTML=`0${order.indexOf(me)+1}<span> / 06</span>`}
function tick(dt){if(state==='count'){count-=dt;$('#countdown').textContent=count>0?Math.ceil(count):'GO!';if(count<=-.6){state='race';$('#countdown').textContent=''}return}if(state!=='race')return;elapsed+=dt;boost=Math.max(0,boost-dt);shield=Math.max(0,shield-dt);flash=Math.max(0,flash-dt);toastTimer-=dt;if(toastTimer<=0)$('#toast').textContent='';let accel=keys.ArrowUp?95:-35;if(keys.ArrowDown)accel=-160;me.v=Math.max(0,Math.min(boost>0?355:MAX,me.v+accel*dt+(boost>0?180*dt:0)));let turn=(keys.ArrowRight?1:0)-(keys.ArrowLeft?1:0);me.x+=turn*dt*(me.v/180)+Math.sin(me.d/1400)*dt*me.v/700;if(Math.abs(me.x)>1){me.v=Math.max(60,me.v-130*dt);me.x=Math.max(-1.25,Math.min(1.25,me.x))}let old=me.d;me.d+=me.v*dt;
racers.forEach(r=>{if(r===me)return;r.v=r.skill+Math.sin(elapsed*.8+r.phase)*12;r.d+=r.v*dt;r.x=Math.sin(elapsed*.55+r.phase)*.78;let gap=r.d-me.d;if(Math.abs(gap)<16&&Math.abs(r.x-me.x)<.2&&flash===0&&shield===0){me.v*=.65;flash=1;toast('앗! 충돌 — 다시 가속하세요');tone(130,.2)}});
if(Math.floor(old/620)!==Math.floor(me.d/620)&&!held){held=['🚀','⭐','❄️'][Math.floor(Math.random()*3)];$('#item').firstChild.textContent=held;toast('선물 획득! SPACE로 사용');tone(1047,.1);setTimeout(()=>tone(1318,.15),100)}
if(Math.floor(old/970)!==Math.floor(me.d/970)){boost=Math.max(boost,1.2);toast('아이스 대시! ✨')}
$('#speed').textContent=Math.round(me.v);$('#lap').innerHTML=`${Math.min(3,Math.floor(me.d/LENGTH)+1)}<span> / 3</span>`;$('#time').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(Math.floor(elapsed%60)).padStart(2,'0')}`;updateGrid();if(me.d>=LENGTH*3)finish()}
function finish(){let rank=[...racers].sort((a,b)=>b.d-a.d).indexOf(me)+1;state='finished';$('#overlay').style.display='flex';$('#overlay h2').textContent=rank===1?'우승! 메리 크리스마스 🏆':`${rank}위 완주! 멋진 레이스 🏁`;$('#overlay p').textContent=`기록 ${$('#time').textContent} · 드라이버를 바꾸어 다시 도전해 보세요.`;$('#start').innerHTML='다시 달리기 <span>↻</span>';tone(523,.2);setTimeout(()=>tone(659,.2),180);setTimeout(()=>tone(784,.5),360)}
function poly(points,color){ctx.fillStyle=color;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fill()}
function round(x,y,w,h,r,col){ctx.fillStyle=col;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function kart(x,y,s,id){ctx.save();ctx.translate(x,y);ctx.scale(s,s);ctx.fillStyle='#09232c66';ctx.beginPath();ctx.ellipse(0,16,26,9,0,0,7);ctx.fill();round(-25,-4,11,26,4,'#102b39');round(14,-4,11,26,4,'#102b39');round(-20,-5,40,26,8,chars[id][2]);round(-16,12,32,8,3,'#eefbff');round(-10,-21,20,25,8,chars[id][2]);ctx.fillStyle='#f9d6ab';ctx.beginPath();ctx.arc(0,-23,11,0,7);ctx.fill();round(-13,-36,26,12,6,chars[id][2]);ctx.fillStyle='white';ctx.font='bold 9px sans-serif';ctx.textAlign='center';ctx.fillText(['M','L','P','Y','T','B'][id],0,-27);ctx.restore()}
let W=1000,H=610;
function draw(t){let d=me?me.d: t*35,h=H*.35;let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#102939');sky.addColorStop(.6,'#34657a');sky.addColorStop(1,'#8db7c9');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
// Aurora, moon and distant mountain silhouettes.
ctx.fillStyle='#70d5bd18';ctx.beginPath();ctx.ellipse(W*.4,50,W*.5,50,-.15,0,7);ctx.fill();ctx.fillStyle='#fff4c8';ctx.beginPath();ctx.arc(W*.77,H*.17,23,0,7);ctx.fill();for(let i=0;i<12;i++){let x=i*W/10;poly([[x-150,h+20],[x,H*.12+(i%3)*16],[x+160,h+20]],i%2?'#628899':'#52788c');poly([[x-27,H*.12+(i%3)*16+35],[x,H*.12+(i%3)*16],[x+35,H*.12+(i%3)*16+45]],'#c6e1e7')}
ctx.fillStyle='#d4e8ed';ctx.fillRect(0,h,W,H-h);
const center=q=>W/2+Math.sin(d/1900+q*2)*W*.09*(1-q)-(me?me.x:0)*W*.22*q;
for(let i=0;i<75;i++){let a=i/75,b=(i+1)/75,ya=h+a*a*(H-h),yb=h+b*b*(H-h),wa=W*(.025+a*.64),wb=W*(.025+b*.64),ca=center(a),cb=center(b),stripe=(Math.floor(d/50)+i)%8<4;poly([[ca-wa-8,ya],[ca+wa+8,ya],[cb+wb+8,yb],[cb-wb-8,yb]],stripe?'#d95565':'#fff8e8');poly([[ca-wa,ya],[ca+wa,ya],[cb+wb,yb],[cb-wb,yb]],i%2?'#85bdcf':'#8bc3d4');for(let lane=-1;lane<=1;lane+=2){if((Math.floor(d/45)+i)%7<3)poly([[ca+wa*lane/3-1,ya],[ca+wa*lane/3+1,ya],[cb+wb*lane/3+2,yb],[cb+wb*lane/3-2,yb]],'#e7fbff88')}}
// Perspective roadside trees, village houses, and gift boxes.
let objects=[];for(let i=0;i<40;i++){let z=((i*130-d*.65)%5200+5200)%5200,q=1-z/5200;objects.push({q,i})}objects.sort((a,b)=>a.q-b.q).forEach(({q,i})=>{let y=h+q*q*(H-h),s=.15+q*1.8,x=center(q)+(i%2?1:-1)*(W*(.05+q*.7));ctx.save();ctx.translate(x,y);ctx.scale(s,s);if(i%7===0){round(-27,-35,54,38,2,'#c77667');poly([[-35,-33],[0,-61],[35,-33]],'#f6fbf8');round(-15,-24,12,13,2,'#ffd993');round(8,-24,12,13,2,'#ffd993')}else{round(-4,-15,8,20,1,'#726b60');poly([[-28,-8],[0,-75],[28,-8]],'#245b57');poly([[-23,-22],[0,-75],[23,-22]],'#d7f2ed');poly([[-17,-44],[0,-82],[17,-44]],'#c2e6e2');for(let j=0;j<4;j++){ctx.fillStyle=['#ffcf75','#ef6d79','#a5ffc9'][j%3];ctx.beginPath();ctx.arc(Math.sin(j*3+i)*14,-20-j*12,2.5,0,7);ctx.fill()}}ctx.restore()});
if(me){racers.filter(r=>r!==me).map(r=>({r,z:r.d-me.d})).filter(o=>o.z>0&&o.z<1700).sort((a,b)=>b.z-a.z).forEach(({r,z})=>{let q=1-z/1700,y=h+q*q*(H-h);kart(center(q)+r.x*W*(.025+q*.64)*.8,y,.18+q*1.3,r.id)});if(shield>0){ctx.fillStyle='#deff8f44';ctx.beginPath();ctx.ellipse(W/2,H*.84,55,63,0,0,7);ctx.fill()}if(boost>0){poly([[W/2-15,H*.88],[W/2,H*.99],[W/2+15,H*.88]],'#caff84')}if(flash===0||Math.floor(t*12)%2===0)kart(W/2+((keys.ArrowRight?1:0)-(keys.ArrowLeft?1:0))*9,H*.85,1.6,selected)}
// A tiny circuit map.
ctx.strokeStyle='#daedf25c';ctx.lineWidth=7;ctx.beginPath();ctx.ellipse(W-75,H-145,42,59,-.4,0,7);ctx.stroke();racers.forEach(r=>{let a=r.d/LENGTH*Math.PI*2-Math.PI/2;ctx.fillStyle=r===me?'#deff8f':chars[r.id][2];ctx.beginPath();ctx.arc(W-75+Math.cos(a)*42,H-145+Math.sin(a)*59,r===me?5:3,0,7);ctx.fill()});
ctx.fillStyle='#f0fcffbb';for(let i=0;i<95;i++){let x=(Math.sin(i*145.7)*.5+.5)*W,y=((i*83+t*(15+i%25))%H);ctx.beginPath();ctx.arc(x+Math.sin(t+i)*12,y,1+i%3*.5,0,7);ctx.fill()}}
function resize(){let r=canvas.getBoundingClientRect();W=r.width;H=r.height;canvas.width=W*devicePixelRatio;canvas.height=H*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0)}new ResizeObserver(resize).observe(canvas);
